using System;
using System.Collections.Generic;

// ======================================================================
//  VOCAL PRESETS, the big library: artist-inspired chains (named "(Artist style)"), R&B, singing, UK, afro & dancehall, emo & rock,
//  ULTIMATE all-in-one chains and ad-libs & FX. Every chain is sound design built from this app's own plugins, inspired by an artist's
//  signature sound (nobody outside their studio knows their engineers' real settings). Some bring a vocal bus (glue and space shared
//  by every vocal routed into it): it is made the first time, and the next preset that uses the same bus finds it already there.
//  Generated by a script: chains are checked by VocalStyles.Check in the tests.
// ======================================================================
static partial class VocalStyles
{
    static void AddLibrary()
    {
        AddLibrary1();
        AddLibrary2();
        AddLibrary3();
        AddLibrary4();
        AddLibrary5();
        AddLibrary6();
        AddLibrary7();
        AddLibrary8();
        AddLibrary9();
        AddLibrary10();
    }
    static void AddLibrary1()
    {
        B("Melodic Trap", "Emo Melodic Sing (Juice WRLD style)", "Purely for singing: quick tuning that still lets the voice crack, warm low mids, a bright edge and a long dark echo for heartbreak hooks. Inspired by their sound.", "@Breath Control{reduce=10} > @Auto-Tune-Style Pitch Corrector{scale=0;speed=12;strength=100;natural=30;range=1} > eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=150;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-2;b1_q=1.1;b3_t=0;b3_f=3200;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-24;ratio=3.5;att=6;rel=90;knee=6;makeup=5} > deess{freq=6800;thr=-30;range=9} > sat{mode=1;drive=6;mix=40} > chorus{rate=0.5;depth=2.5;delay=14;spread=85;mix=18} > @Dark Echo{mix=22} > reverb{size=70;damp=55;pre=25;width=100;lc=300;hc=10000;mix=18}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Freestyle Melodic (Juice WRLD style)", "For long off-the-dome melodic takes: forgiving tuning, a rider that evens out the level and a wide echo so every bar floats. Inspired by their sound.", "@Vocal Rider{target=-20;range=9} > @Auto-Tune-Style Pitch Corrector{scale=0;speed=20;strength=95;natural=40;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3000;b3_g=2;b5_t=2;b5_f=11000;b5_g=2.5} > comp{thr=-22;ratio=3;att=8;rel=110;knee=6;makeup=4} > deess{freq=7000;thr=-30;range=8} > @Worldwide Echo{mix=25} > reverb{size=60;damp=50;pre=20;width=100;lc=200;hc=10000;mix=16}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Toxic Love Hook (Juice WRLD style)", "A hook voice with a soft harmony under it, chorus width and a glossy plate: emotional and big. Inspired by their sound.", "@Melody Tune: Soft Harmony{scale=0} > eq{hp_on=1;hp_f=100;hp_s=0;b1_t=0;b1_f=280;b1_g=-2.5;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=12000;b5_g=3.5} > comp{thr=-22;ratio=3;att=10;rel=100;knee=6;makeup=4} > deess{freq=7000;thr=-29;range=9} > chorus{rate=0.6;depth=3;delay=14;spread=80;mix=22} > reverb{size=65;damp=45;pre=25;width=100;lc=200;hc=10000;mix=20}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Rage & Hyper", "Baby Voice Rage (Playboi Carti style)", "The high, squeaky baby voice: formant pushed up, hard tune, crushed and bright with a wide room. Inspired by their sound.", "@Formant Shifter{shift=4;tilt=2;mix=100} > @Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=180;hp_s=1;b3_t=0;b3_f=4000;b3_g=3;b5_t=2;b5_f=12000;b5_g=5} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=7} > sat{mode=2;drive=10;mix=45} > widener{width=140;bass=120} > reverb{size=25;damp=50;pre=8;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Rage & Hyper", "Deep Rage Voice (Playboi Carti style)", "The deep, distorted voice from the rage records: formant down, hard clipped and loud. Inspired by their sound.", "@Formant Shifter{shift=-3;tilt=-1;mix=100} > eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=140;b0_g=2;b3_t=0;b3_f=3000;b3_g=2} > dist{mode=0;drive=16;tone=6000;mix=40;level=-6} > comp{thr=-26;ratio=6;att=3;rel=60;knee=6;makeup=7} > @Hard Clipper{drive=10;mix=60} > widener{width=125;bass=120}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Rage & Hyper", "Vampire Rage (Ken Carson style)", "Dark, buzzy and loud: fuzz under the voice, hard tune, gritty top and a short room. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=140;hp_s=1;b1_t=0;b1_f=350;b1_g=-3;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=11000;b5_g=3} > dist{mode=2;drive=12;tone=5000;mix=30;level=-6} > comp{thr=-25;ratio=5;att=4;rel=70;knee=6;makeup=6} > widener{width=130;bass=120} > reverb{size=30;damp=55;pre=10;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Rage & Hyper", "Opium Lead (Destroy Lonely style)", "Laid-back rage: soft hard-tune, dark top, lots of chorus and a smoky reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=5;strength=100;natural=10;range=1} > eq{hp_on=1;hp_f=120;hp_s=0;lp_on=1;lp_f=13000;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-24;ratio=4;att=8;rel=90;knee=6;makeup=5} > sat{mode=1;drive=8;mix=50} > chorus{rate=0.4;depth=4;delay=14;spread=80;mix=30} > reverb{size=55;damp=65;pre=20;width=100;lc=200;hc=10000;mix=18}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Rage & Hyper", "Bell Tune (Yeat style)", "The ringing, bell-like autotune: snapped hard, formant a touch up, bright and wide with a quick echo. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > @Formant Shifter{shift=1.5;tilt=1;mix=100} > eq{hp_on=1;hp_f=150;hp_s=1;b3_t=0;b3_f=4200;b3_g=3;b5_t=2;b5_f=12500;b5_g=4.5} > comp{thr=-25;ratio=5;att=3;rel=60;knee=6;makeup=6} > exciter{drive=12;harm=60;flo=4000;fhi=16000;mix=40} > widener{width=140;bass=120} > @Rap Ad-Lib Echo{mix=18}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Rage & Hyper", "Rage Scream (Lil Uzi Vert style)", "High-energy and bright: hard tune, saturated, wide and pushed hard for the screams. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=2} > eq{hp_on=1;hp_f=150;hp_s=1;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3800;b3_g=3;b5_t=2;b5_f=12000;b5_g=4} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=7} > sat{mode=2;drive=12;mix=50} > widener{width=140;bass=120} > reverb{size=30;damp=45;pre=10;width=100;lc=200;hc=10000;mix=12}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Melodic Trap", "Melodic Bounce (Lil Uzi Vert style)", "The bouncy, high melodic flow: fast tuning, airy top and a wide echo on every line end. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=5;strength=100;natural=15;range=1} > eq{hp_on=1;hp_f=140;hp_s=0;b3_t=0;b3_f=3800;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=4} > comp{thr=-24;ratio=4;att=5;rel=70;knee=6;makeup=5} > exciter{drive=10;harm=50;flo=4000;fhi=16000;mix=30} > chorus{rate=0.7;depth=3;delay=14;spread=80;mix=20} > @Airy Echo{mix=22}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Astro Lead (Travis Scott style)", "Heavy tune, dark grit, huge reverb and delay throws: the psychedelic stadium sound. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-25;ratio=4.5;att=5;rel=80;knee=6;makeup=6} > sat{mode=1;drive=10;mix=55} > chorus{rate=0.5;depth=3;delay=14;spread=80;mix=25} > @Stadium Echo{mix=26} > reverb{size=85;damp=55;pre=35;width=100;lc=300;hc=9000;mix=28}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Rodeo Dark Verse (Travis Scott style)", "Darker and closer for verses: tuned, low-passed, distorted underneath with a long dark echo. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=120;hp_s=0;lp_on=1;lp_f=11000;b1_t=0;b1_f=350;b1_g=-2} > comp{thr=-26;ratio=5;att=4;rel=70;knee=6;makeup=6} > dist{mode=0;drive=10;tone=4500;mix=25;level=-6} > @Dark Echo{mix=28} > reverb{size=70;damp=70;pre=25;width=100;lc=200;hc=10000;mix=20}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Psychedelic Ad-Libs (Travis Scott style)", "The \"it's lit\" ad-libs: thin, distorted, panned wide into a stadium echo. Inspired by their sound.", "eq{hp_on=1;hp_f=300;hp_s=1;b3_t=0;b3_f=3500;b3_g=4} > dist{mode=0;drive=14;tone=6000;mix=45;level=-6} > widener{width=170;bass=120} > @Stadium Echo{mix=40} > reverb{size=80;damp=50;pre=30;width=100;lc=200;hc=10000;mix=30}", null, null, "Lead");
        B("Melodic Trap", "Dirty Sprite Lead (Future style)", "Dark, slurred autotune: fast tune, warm low end, tube grit and a dark echo trail. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=3;strength=100;natural=8;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;lp_on=1;lp_f=13000;b0_t=1;b0_f=160;b0_g=2;b1_t=0;b1_f=320;b1_g=-1.5;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-26;ratio=5;att=6;rel=80;knee=6;makeup=6} > sat{mode=1;drive=10;mix=55} > @Dark Echo{mix=20} > reverb{size=50;damp=65;pre=15;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Melodic Trap", "Mask Off Melody (Future style)", "Smoother melodic Future: tuned, warm, chorus-wide with a soft plate. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=8;strength=100;natural=20;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;b0_t=1;b0_f=150;b0_g=1.5;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-24;ratio=4;att=8;rel=90;knee=6;makeup=5} > chorus{rate=0.5;depth=3;delay=14;spread=80;mix=22} > reverb{size=60;damp=50;pre=20;width=100;lc=200;hc=10000;mix=18}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Slime Wail (Young Thug style)", "The wild, whiny melodic voice: hard tune, nasal presence boost, bright and wide. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=2} > eq{hp_on=1;hp_f=140;hp_s=0;b2_t=0;b2_f=1000;b2_g=2;b2_q=1.5;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=12000;b5_g=3.5} > comp{thr=-25;ratio=4.5;att=4;rel=70;knee=6;makeup=6} > sat{mode=0;drive=8;mix=40} > widener{width=135;bass=120} > @Rap Ad-Lib Echo{mix=20}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Smooth Drip (Gunna style)", "Silky, smooth melodic flow: gentle fast tune, warm and close, wide chorus, soft echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=10;strength=100;natural=25;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;b0_t=1;b0_f=150;b0_g=1.5;b1_t=0;b1_f=300;b1_g=-1.5;b3_t=0;b3_f=3000;b3_g=1.5;b5_t=2;b5_f=12000;b5_g=2.5} > comp{thr=-23;ratio=3.5;att=10;rel=100;knee=6;makeup=4} > deess{freq=6800;thr=-30;range=9} > chorus{rate=0.45;depth=3;delay=14;spread=80;mix=25} > @Airy Echo{mix=18} > reverb{size=55;damp=45;pre=20;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Pain Melody (Lil Durk style)", "Heavy melodic autotune with grit: hard tune, mid-forward, saturated and tight. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b2_t=0;b2_f=900;b2_g=1.5;b3_t=0;b3_f=3200;b3_g=2.5} > comp{thr=-25;ratio=5;att=5;rel=75;knee=6;makeup=6} > sat{mode=1;drive=9;mix=50} > deess{freq=7000;thr=-29;range=9} > @Worldwide Echo{mix=16} > reverb{size=40;damp=55;pre=12;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Melodic Trap", "Piano Pain (Polo G style)", "Clear melodic rap over piano: natural tune, bright and clean with a soft plate. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=25;strength=100;natural=45;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3300;b3_g=2.5;b5_t=2;b5_f=11500;b5_g=3} > comp{thr=-23;ratio=3.5;att=8;rel=100;knee=6;makeup=4} > deess{freq=7000;thr=-30;range=9} > reverb{size=55;damp=45;pre=20;width=100;lc=200;hc=10000;mix=15}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Singing", "Soul Pain Sing (Rod Wave style)", "Purely for singing: soulful and warm, gentle tuning, rich low mids, tube warmth and a big plate. Inspired by their sound.", "@Breath Control{reduce=10} > @Auto-Tune-Style Pitch Corrector{scale=0;speed=30;strength=90;natural=55;range=1} > eq{hp_on=1;hp_f=85;hp_s=0;b0_t=1;b0_f=180;b0_g=2;b1_t=0;b1_f=330;b1_g=-1.5;b3_t=0;b3_f=3000;b3_g=2;b5_t=2;b5_f=11000;b5_g=2.5} > comp{thr=-22;ratio=3;att=12;rel=130;knee=6;makeup=4} > deess{freq=6800;thr=-30;range=9} > sat{mode=1;drive=6;mix=40} > reverb{size=75;damp=40;pre=35;width=100;lc=200;hc=10000;mix=22}", "Vocal Bus (Singer)", "comp{thr=-20;ratio=2;att=30;rel=200;knee=10;makeup=2} > reverb{size=75;damp=35;pre=40;width=100;lc=300;hc=13000;mix=22} > delay{mode=2;sync=3;time=375;fb=28;lc=200;hc=6000;mix=9}", "Lead");
        B("Melodic Trap", "Raspy Melodic (NBA YoungBoy style)", "Raspy, emotional melodic rap: tuned, mid-forward grit, compressed hard with a short echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=8;strength=100;natural=20;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b2_t=0;b2_f=1100;b2_g=2;b3_t=0;b3_f=3000;b3_g=2.5;b5_t=2;b5_f=10000;b5_g=1.5} > comp{thr=-26;ratio=5;att=5;rel=75;knee=6;makeup=6} > sat{mode=2;drive=10;mix=45} > deess{freq=6800;thr=-29;range=9} > @Rap Ad-Lib Echo{mix=16}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Melodic Trap", "Melodic Trap Polish (Lil Baby style)", "Tight melodic trap: quick tune, clean presence, fast compression, short echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=6;strength=100;natural=20;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2.5;b3_t=0;b3_f=3500;b3_g=2.5;b5_t=2;b5_f=11000;b5_g=2.5} > comp{thr=-25;ratio=4;att=5;rel=75;knee=6;makeup=5} > deess{freq=7000;thr=-30;range=9} > @Rap Ad-Lib Echo{mix=14} > reverb{size=30;damp=55;pre=10;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Melodic Trap", "Teen Melody (Lil Tecca style)", "Light, bright and bouncy: fast tune, airy top, wide and clean. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=5;strength=100;natural=15;range=1} > eq{hp_on=1;hp_f=140;hp_s=0;b3_t=0;b3_f=3800;b3_g=2.5;b5_t=2;b5_f=12500;b5_g=4} > comp{thr=-23;ratio=3.5;att=6;rel=80;knee=6;makeup=4} > chorus{rate=0.6;depth=2.5;delay=14;spread=80;mix=18} > @Airy Echo{mix=16}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Melodic NY (A Boogie wit da Hoodie style)", "Smooth melodic NY: warm tune, round lows, chorus and a soft echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=12;strength=100;natural=30;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;b0_t=1;b0_f=160;b0_g=1.5;b3_t=0;b3_f=3000;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-23;ratio=3.5;att=10;rel=100;knee=6;makeup=4} > chorus{rate=0.5;depth=2.5;delay=14;spread=80;mix=20} > @Worldwide Echo{mix=16}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Melodic Tjay (Lil Tjay style)", "High, sweet melodic voice: fast tune, bright presence and a long airy echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=5;strength=100;natural=20;range=1} > eq{hp_on=1;hp_f=130;hp_s=0;b3_t=0;b3_f=3600;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=3.5} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > deess{freq=7200;thr=-30;range=9} > @Airy Echo{mix=22} > reverb{size=55;damp=45;pre=20;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Box Melodic (Roddy Ricch style)", "Warm, high melodic rap: soft tune, round body, chorus and a quick slap. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=10;strength=100;natural=25;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-1.5;b3_t=0;b3_f=3200;b3_g=2} > comp{thr=-24;ratio=4;att=8;rel=90;knee=6;makeup=5} > chorus{rate=0.5;depth=2.5;delay=14;spread=80;mix=18} > delay{mode=0;sync=0;time=110;fb=10;lc=200;hc=6000;mix=14}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Psychedelic Croon (Don Toliver style)", "Smooth, dreamy croon: gentle tune, chorus, phaser-like width and lush echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=15;strength=100;natural=35;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;b3_t=0;b3_f=3000;b3_g=2;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-22;ratio=3;att=12;rel=120;knee=6;makeup=4} > chorus{rate=0.35;depth=5;delay=14;spread=100;mix=35} > @Worldwide Echo{mix=22} > reverb{size=75;damp=40;pre=30;width=100;lc=200;hc=10000;mix=22}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "Bubbly Melodic (Trippie Redd style)", "Melodic and big: tuned, a touch of grit, bright top and a huge reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=8;strength=100;natural=20;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b3_t=0;b3_f=3500;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > sat{mode=1;drive=8;mix=40} > reverb{size=80;damp=45;pre=30;width=100;lc=200;hc=10000;mix=22}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Emo & Rock Rap", "Rock Scream (Trippie Redd style)", "For the rock-rap screams: distorted, compressed hard, wide and loud. Inspired by their sound.", "eq{hp_on=1;hp_f=140;hp_s=1;b2_t=0;b2_f=1200;b2_g=2;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=0;drive=18;tone=6000;mix=45;level=-6} > comp{thr=-26;ratio=6;att=3;rel=60;knee=6;makeup=7} > widener{width=130;bass=120} > reverb{size=35;damp=50;pre=10;width=100;lc=200;hc=10000;mix=12}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Emo & Rock Rap", "Sad Lo-Fi Emo (Lil Peep style)", "Lo-fi emo singing: soft tune, band-limited, tape-warm, doubled and drowned in reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=25;strength=90;natural=50;range=1} > eq{hp_on=1;hp_f=180;hp_s=0;lp_on=1;lp_f=9000;b2_t=0;b2_f=900;b2_g=1.5} > comp{thr=-22;ratio=3;att=12;rel=120;knee=6;makeup=4} > sat{mode=0;drive=10;mix=60} > chorus{rate=0.4;depth=3;delay=14;spread=80;mix=30} > reverb{size=80;damp=60;pre=30;width=100;lc=200;hc=10000;mix=30}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Emo & Rock Rap", "Distorted Emo (XXXTentacion style)", "Raw and blown-out for the heavy records: distorted, clipped and right in your face. Inspired by their sound.", "eq{hp_on=1;hp_f=150;hp_s=1;lp_on=1;lp_f=12000;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=0;drive=22;tone=6000;mix=55;level=-6} > @Hard Clipper{drive=12;mix=70} > comp{thr=-26;ratio=6;att=3;rel=60;knee=6;makeup=6} > reverb{size=20;damp=60;pre=6;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Singing", "Soft Sad Sing (XXXTentacion style)", "The soft, sad singing side: barely tuned, warm, close and a long airy reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=40;strength=80;natural=65;range=1} > eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-1.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-22;ratio=2.5;att=15;rel=140;knee=6;makeup=3} > deess{freq=6800;thr=-31;range=8} > reverb{size=75;damp=40;pre=30;width=100;lc=200;hc=10000;mix=25}", "Vocal Bus (Singer)", "comp{thr=-20;ratio=2;att=30;rel=200;knee=10;makeup=2} > reverb{size=75;damp=35;pre=40;width=100;lc=300;hc=13000;mix=22} > delay{mode=2;sync=3;time=375;fb=28;lc=200;hc=6000;mix=9}", "Lead");
        B("Pop Rap", "Smooth OVO (Drake style)", "The smooth Drake verse: clean, warm and close, gentle compression, a dark low-passed top and a soft room. Inspired by their sound.", "eq{hp_on=1;hp_f=90;hp_s=0;lp_on=1;lp_f=15000;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-2;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-23;ratio=3;att=10;rel=120;knee=6;makeup=4} > deess{freq=6600;thr=-30;range=9} > sat{mode=1;drive=4;mix=30} > reverb{size=35;damp=60;pre=15;width=100;lc=300;hc=9000;mix=10}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "OVO Melodic (Drake style)", "The melodic, sung Drake hooks: soft tuning, warm body, dark plate and a slow echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=18;strength=100;natural=40;range=1} > eq{hp_on=1;hp_f=90;hp_s=0;lp_on=1;lp_f=14500;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-1.5;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-22;ratio=3;att=12;rel=130;knee=6;makeup=4} > deess{freq=6600;thr=-30;range=9} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10} > reverb{size=60;damp=55;pre=25;width=100;lc=300;hc=9000;mix=16}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("Pop Rap", "Toronto Late Night (Drake style)", "The dark, moody late-night sound: low-passed, close and warm with a long dark tail. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;lp_on=1;lp_f=11000;b1_t=0;b1_f=300;b1_g=-1.5} > comp{thr=-24;ratio=3.5;att=10;rel=120;knee=6;makeup=5} > sat{mode=1;drive=6;mix=40} > @Dark Echo{mix=18} > reverb{size=70;damp=70;pre=30;width=100;lc=300;hc=7000;mix=18}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("Pop Rap", "Laid-Back Flex (Jack Harlow style)", "Easy and smooth: natural, slightly bright, light compression and a small room. Inspired by their sound.", "eq{hp_on=1;hp_f=95;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-21;ratio=3;att=12;rel=120;knee=6;makeup=3} > deess{freq=6800;thr=-30;range=8} > reverb{size=28;damp=55;pre=10;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("Storytelling", "Rapid Fire (Eminem style)", "Fast, aggressive and crystal clear: hard compression, strong presence and de-essing so every syllable lands. Inspired by their sound.", "eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-3;b1_q=1.2;b3_t=0;b3_f=3500;b3_g=3.5;b4_t=0;b4_f=7000;b4_g=-1;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-28;ratio=6;att=2;rel=60;knee=4;makeup=8} > deess{freq=6800;thr=-28;range=10} > exciter{drive=8;harm=50;flo=3500;fhi=16000;mix=25} > reverb{size=18;damp=65;pre=5;width=100;lc=200;hc=10000;mix=5}", "Vocal Bus (UK)", "comp{thr=-18;ratio=2.5;att=15;rel=120;knee=6;makeup=2} > reverb{size=22;damp=60;pre=8;width=100;lc=300;hc=9000;mix=6}", "Lead");
        B("Storytelling", "Angry Verse (Eminem style)", "The shouty, aggressive verse: gritty, in-your-face, loud with a hard double feel. Inspired by their sound.", "eq{hp_on=1;hp_f=120;hp_s=0;b2_t=0;b2_f=1000;b2_g=2;b3_t=0;b3_f=3200;b3_g=3.5} > comp{thr=-28;ratio=7;att=2;rel=55;knee=4;makeup=9} > sat{mode=2;drive=12;mix=45} > chorus{rate=1.2;depth=1.5;delay=10;spread=100;mix=15} > reverb{size=15;damp=70;pre=5;width=100;lc=200;hc=10000;mix=4}", null, null, "Lead");
        B("Storytelling", "Slim Shady Voice (Eminem style)", "The nasal, high Slim Shady voice: formant up a touch, nasal boost and bright and dry. Inspired by their sound.", "@Formant Shifter{shift=2;tilt=1;mix=100} > eq{hp_on=1;hp_f=140;hp_s=0;b2_t=0;b2_f=1200;b2_g=3;b2_q=1.5;b3_t=0;b3_f=3500;b3_g=3} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=7} > deess{freq=7000;thr=-28;range=9} > reverb{size=12;damp=70;pre=4;width=100;lc=200;hc=10000;mix=4}", null, null, "Lead");
        B("Storytelling", "Dark Lyricist (NF style)", "Intense and dark: tight, aggressive, a dark long reverb behind the bars. Inspired by their sound.", "eq{hp_on=1;hp_f=110;hp_s=0;lp_on=1;lp_f=13000;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=3} > comp{thr=-27;ratio=6;att=3;rel=60;knee=6;makeup=7} > deess{freq=6800;thr=-29;range=9} > @Dark Echo{mix=16} > reverb{size=70;damp=65;pre=25;width=100;lc=200;hc=10000;mix=16}", "Vocal Bus (UK)", "comp{thr=-18;ratio=2.5;att=15;rel=120;knee=6;makeup=2} > reverb{size=22;damp=60;pre=8;width=100;lc=300;hc=9000;mix=6}", "Lead");
        B("Storytelling", "Speed Flow (Logic style)", "Clean fast flow: precise compression, bright and dry for rapid bars. Inspired by their sound.", "eq{hp_on=1;hp_f=105;hp_s=0;b1_t=0;b1_f=300;b1_g=-2.5;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-26;ratio=5;att=2;rel=60;knee=4;makeup=7} > deess{freq=7000;thr=-29;range=9} > reverb{size=15;damp=65;pre=5;width=100;lc=200;hc=10000;mix=5}", "Vocal Bus (UK)", "comp{thr=-18;ratio=2.5;att=15;rel=120;knee=6;makeup=2} > reverb{size=22;damp=60;pre=8;width=100;lc=300;hc=9000;mix=6}", "Lead");
        B("Storytelling", "Conscious Lead (Kendrick Lamar style)", "Clear, punchy and versatile: natural tone, presence and controlled dynamics with a tight room. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;b1_t=0;b1_f=320;b1_g=-2.5;b3_t=0;b3_f=3300;b3_g=2.5;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-25;ratio=4.5;att=4;rel=80;knee=6;makeup=6} > deess{freq=6800;thr=-30;range=9} > sat{mode=0;drive=5;mix=30} > reverb{size=22;damp=60;pre=8;width=100;lc=200;hc=10000;mix=7}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Storytelling", "High Voice Character (Kendrick Lamar style)", "The high, pinched character voice: formant up, nasal and squeezed. Inspired by their sound.", "@Formant Shifter{shift=3;tilt=2;mix=100} > eq{hp_on=1;hp_f=160;hp_s=0;b2_t=0;b2_f=1100;b2_g=3;b3_t=0;b3_f=3800;b3_g=2.5} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=7} > reverb{size=15;damp=65;pre=5;width=100;lc=200;hc=10000;mix=5}", null, null, "Lead");
        B("Storytelling", "Low Voice Character (Kendrick Lamar style)", "The deep, menacing character voice: formant down, dark and heavy. Inspired by their sound.", "@Formant Shifter{shift=-3;tilt=-2;mix=100} > eq{hp_on=1;hp_f=70;hp_s=0;lp_on=1;lp_f=10000;b0_t=1;b0_f=130;b0_g=2} > comp{thr=-26;ratio=5;att=5;rel=80;knee=6;makeup=6} > sat{mode=1;drive=6;mix=40} > reverb{size=25;damp=70;pre=8;width=100;lc=200;hc=10000;mix=8}", null, null, "Lead");
        B("Boom Bap", "Warm Storyteller (J. Cole style)", "Natural, warm and honest: no tuning, rich low mids, gentle compression and a small warm room. Inspired by their sound.", "eq{hp_on=1;hp_f=85;hp_s=0;lp_on=1;lp_f=15000;b0_t=1;b0_f=170;b0_g=2;b1_t=0;b1_f=350;b1_g=-1;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-21;ratio=3;att=15;rel=140;knee=6;makeup=4} > deess{freq=6600;thr=-31;range=8} > sat{mode=0;drive=5;mix=40} > reverb{size=25;damp=60;pre=10;width=100;lc=200;hc=10000;mix=9}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Raw Poet (Nas style)", "Classic NY lyricist: mid-forward, warm tape, gentle compression and a short room. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;lp_on=1;lp_f=13000;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=2800;b3_g=2} > comp{thr=-21;ratio=3;att=14;rel=130;knee=6;makeup=4} > sat{mode=0;drive=7;mix=45} > reverb{size=20;damp=65;pre=8;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Big Room Legend (Biggie style)", "Big, round and booming: warm lows, heavy tape, a slap and a big room. Inspired by their sound.", "eq{hp_on=1;hp_f=75;hp_s=0;lp_on=1;lp_f=12500;b0_t=1;b0_f=150;b0_g=2.5;b1_t=0;b1_f=350;b1_g=-1;b3_t=0;b3_f=2800;b3_g=2} > comp{thr=-22;ratio=3.5;att=15;rel=140;knee=6;makeup=5} > sat{mode=0;drive=9;mix=55} > delay{mode=0;sync=0;time=120;fb=12;lc=200;hc=6000;mix=12} > reverb{size=35;damp=60;pre=12;width=100;lc=200;hc=10000;mix=12}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Raw West Coast (Tupac style)", "Raw, passionate and gritty: mid-forward, saturated and a little room. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;lp_on=1;lp_f=12000;b2_t=0;b2_f=1100;b2_g=2;b3_t=0;b3_f=3000;b3_g=2.5} > comp{thr=-24;ratio=4;att=8;rel=100;knee=6;makeup=5} > sat{mode=2;drive=10;mix=50} > reverb{size=22;damp=60;pre=8;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Executive Verse (Jay-Z style)", "Smooth and in control: clean presence, even compression and a polished plate. Inspired by their sound.", "eq{hp_on=1;hp_f=95;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-22;ratio=3.5;att=10;rel=110;knee=6;makeup=4} > deess{freq=6800;thr=-30;range=8} > reverb{size=35;damp=50;pre=15;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Gravel Bark (DMX style)", "Raspy and barking: distorted mids, hard compression, loud and aggressive. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;b2_t=0;b2_f=1000;b2_g=3;b3_t=0;b3_f=2800;b3_g=2.5} > dist{mode=0;drive=14;tone=5000;mix=35;level=-6} > comp{thr=-27;ratio=6;att=3;rel=60;knee=6;makeup=7} > reverb{size=18;damp=65;pre=6;width=100;lc=200;hc=10000;mix=6}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Old School", "Laid-Back G (Snoop Dogg style)", "Smooth and lazy West Coast: warm, soft compression, a little tape and a slap echo. Inspired by their sound.", "eq{hp_on=1;hp_f=90;hp_s=0;lp_on=1;lp_f=13000;b0_t=1;b0_f=160;b0_g=1.5;b3_t=0;b3_f=2800;b3_g=1.5} > comp{thr=-21;ratio=3;att=18;rel=150;knee=6;makeup=4} > sat{mode=0;drive=6;mix=45} > delay{mode=0;sync=0;time=110;fb=15;lc=200;hc=6000;mix=14} > reverb{size=30;damp=55;pre=10;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Old School", "Street Hustler (50 Cent style)", "Thick, confident and close: warm low end, steady compression, a quick double feel. Inspired by their sound.", "eq{hp_on=1;hp_f=90;hp_s=0;lp_on=1;lp_f=13500;b0_t=1;b0_f=150;b0_g=2;b3_t=0;b3_f=3000;b3_g=2} > comp{thr=-23;ratio=4;att=10;rel=110;knee=6;makeup=5} > chorus{rate=1;depth=1.2;delay=10;spread=100;mix=12} > reverb{size=25;damp=60;pre=8;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Old School", "Golden Era (Dr. Dre era style)", "Polished G-funk vocal: clean, warm, controlled with a bright plate. Inspired by their sound.", "eq{hp_on=1;hp_f=95;hp_s=0;b0_t=1;b0_f=150;b0_g=1;b1_t=0;b1_f=320;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-22;ratio=3.5;att=10;rel=120;knee=6;makeup=4} > deess{freq=6800;thr=-30;range=8} > reverb{size=40;damp=45;pre=15;width=100;lc=200;hc=10000;mix=12}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Boom Bap", "Hungry Lyricist (Joey Bada$$ style)", "Dusty modern boom bap: warm, saturated, slightly dark with a small room. Inspired by their sound.", "eq{hp_on=1;hp_f=100;hp_s=0;lp_on=1;lp_f=12000;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=3000;b3_g=2} > comp{thr=-22;ratio=3.5;att=12;rel=120;knee=6;makeup=4} > sat{mode=0;drive=8;mix=50} > reverb{size=22;damp=65;pre=8;width=100;lc=200;hc=10000;mix=9}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Rage & Hyper", "Hyper Lyricist (Denzel Curry style)", "Aggressive, versatile energy: gritty, compressed hard, bright and punchy. Inspired by their sound.", "eq{hp_on=1;hp_f=120;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-27;ratio=6;att=3;rel=60;knee=6;makeup=7} > sat{mode=2;drive=10;mix=45} > reverb{size=20;damp=60;pre=6;width=100;lc=200;hc=10000;mix=7}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Pop Rap", "Jazzy Smooth (Mac Miller style)", "Mellow and warm: natural, soft compression, tape warmth and a soft room. Inspired by their sound.", "eq{hp_on=1;hp_f=90;hp_s=0;lp_on=1;lp_f=14000;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=330;b1_g=-1;b3_t=0;b3_f=3000;b3_g=1.5} > comp{thr=-20;ratio=2.5;att=18;rel=150;knee=6;makeup=3} > sat{mode=0;drive=6;mix=45} > reverb{size=40;damp=55;pre=15;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("Pop Rap", "Creative Weird (Tyler, The Creator style)", "Characterful and gritty: deep, distorted lightly, bright presence, a dry room. Inspired by their sound.", "eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=140;b0_g=1.5;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=3200;b3_g=2} > comp{thr=-25;ratio=4.5;att=5;rel=80;knee=6;makeup=6} > dist{mode=0;drive=10;tone=6000;mix=25;level=-6} > reverb{size=22;damp=60;pre=8;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Pop Rap", "Pretty Flacko (A$AP Rocky style)", "Stylish and smooth: clean presence, light tune, a little chorus and a dark echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=30;strength=70;natural=60;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-23;ratio=3.5;att=8;rel=100;knee=6;makeup=4} > chorus{rate=0.5;depth=2;delay=14;spread=80;mix=15} > @Dark Echo{mix=14}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Cloud & Lo-Fi", "Moody Hum (Kid Cudi style)", "The moody humming voice: warm, chorused, big soft reverb and an endless echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=30;strength=85;natural=55;range=1} > eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=160;b0_g=1.5;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-21;ratio=3;att=15;rel=140;knee=6;makeup=3} > chorus{rate=0.35;depth=4;delay=14;spread=100;mix=35} > reverb{size=85;damp=50;pre=35;width=100;lc=200;hc=10000;mix=32} > @Infinite Space{mix=14}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Melodic Trap", "808s Robot Sing (Kanye West style)", "The 808s & Heartbreak autotune singing: hard tune, cold and wide with a long reverb. Inspired by their sound.", "@Hard Tune{scale=0;speed=0;strength=100;natural=0;range=1} > eq{hp_on=1;hp_f=120;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=2;b5_t=2;b5_f=11000;b5_g=2.5} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > widener{width=130;bass=120} > reverb{size=80;damp=50;pre=30;width=100;lc=200;hc=10000;mix=24}", "Vocal Bus (Melodic)", "comp{thr=-18;ratio=2;att=25;rel=180;knee=8;makeup=2} > chorus{rate=0.4;depth=2;delay=14;spread=90;mix=12} > reverb{size=70;damp=45;pre=30;width=100;lc=300;hc=11000;mix=16} > delay{mode=2;sync=3;time=375;fb=30;lc=200;hc=6000;mix=10}", "Lead");
        B("Rage & Hyper", "Yeezus Distortion (Kanye West style)", "Industrial and harsh: blown-out distortion, clipped and loud with a short room. Inspired by their sound.", "eq{hp_on=1;hp_f=140;hp_s=0;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=0;drive=24;tone=5000;mix=55;level=-6} > @Hard Clipper{drive=14;mix=70} > comp{thr=-26;ratio=6;att=3;rel=60;knee=6;makeup=6} > reverb{size=18;damp=60;pre=6;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Boom Bap", "Chipmunk Soul Verse (Kanye West style)", "The early soul-sample era: warm, mid-forward, tape-saturated with a small room. Inspired by their sound.", "eq{hp_on=1;hp_f=95;hp_s=0;lp_on=1;lp_f=13000;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=3000;b3_g=2} > comp{thr=-22;ratio=3.5;att=10;rel=120;knee=6;makeup=4} > sat{mode=0;drive=8;mix=50} > reverb{size=25;damp=60;pre=10;width=100;lc=200;hc=10000;mix=9}", "Vocal Bus (Boom Bap)", "comp{thr=-18;ratio=2;att=30;rel=150;knee=8;makeup=2} > sat{mode=0;drive=4;mix=30} > reverb{size=24;damp=60;pre=10;width=100;lc=250;hc=8000;mix=9}", "Lead");
        B("Melodic Trap", "Raspy Autotune (Lil Wayne style)", "The raspy autotune: fast tune, gritty mids, compressed and bright. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=4;strength=100;natural=10;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b2_t=0;b2_f=1100;b2_g=2.5;b3_t=0;b3_f=3200;b3_g=2.5;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-26;ratio=5;att=4;rel=70;knee=6;makeup=6} > sat{mode=2;drive=9;mix=45} > @Rap Ad-Lib Echo{mix=14}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Dark Monotone (21 Savage style)", "Dark, dry and calm: low and close, low-passed top, hard compression and almost no space. Inspired by their sound.", "eq{hp_on=1;hp_f=85;hp_s=0;lp_on=1;lp_f=11000;b0_t=1;b0_f=150;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-2} > comp{thr=-27;ratio=5;att=6;rel=80;knee=6;makeup=7} > sat{mode=1;drive=6;mix=40} > reverb{size=15;damp=75;pre=5;width=100;lc=200;hc=10000;mix=5}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Migos Flow (Migos style)", "The triplet flow: bright, tight and punchy with ad-lib echoes on the line ends. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=10;strength=85;natural=25;range=1} > eq{hp_on=1;hp_f=120;hp_s=0;b1_t=0;b1_f=300;b1_g=-2.5;b3_t=0;b3_f=3600;b3_g=3;b5_t=2;b5_f=11500;b5_g=3} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=6} > deess{freq=7000;thr=-29;range=9} > @Rap Ad-Lib Echo{mix=18}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Punchy Bounce (DaBaby style)", "Loud, punchy and dry: fast compression, strong presence, no space. Inspired by their sound.", "eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2.5;b3_t=0;b3_f=3500;b3_g=3.5} > comp{thr=-27;ratio=6;att=2;rel=55;knee=4;makeup=8} > deess{freq=7000;thr=-28;range=9} > sat{mode=0;drive=6;mix=30}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Memphis Flow (Moneybagg Yo style)", "Thick, confident Memphis trap: warm, compressed and dark-topped with a short echo. Inspired by their sound.", "eq{hp_on=1;hp_f=95;hp_s=0;lp_on=1;lp_f=13000;b0_t=1;b0_f=150;b0_g=1.5;b3_t=0;b3_f=3000;b3_g=2} > comp{thr=-25;ratio=4.5;att=6;rel=80;knee=6;makeup=6} > sat{mode=1;drive=7;mix=40} > @Rap Ad-Lib Echo{mix=12}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Florida Raw (Kodak Black style)", "Raw, raspy and melodic in places: gritty, mid-forward, tight compression. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=20;strength=75;natural=40;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b2_t=0;b2_f=1100;b2_g=2;b3_t=0;b3_f=3000;b3_g=2} > comp{thr=-26;ratio=5;att=5;rel=75;knee=6;makeup=6} > sat{mode=2;drive=9;mix=45} > reverb{size=22;damp=60;pre=8;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Trap", "Tough Lead (Rich The Kid style)", "Clean trap lead: tuned lightly, bright presence, fast compression and a short echo. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=12;strength=85;natural=30;range=1} > eq{hp_on=1;hp_f=115;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3500;b3_g=2.5;b5_t=2;b5_f=11000;b5_g=2.5} > comp{thr=-25;ratio=4.5;att=4;rel=70;knee=6;makeup=6} > @Rap Ad-Lib Echo{mix=14}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Phonk", "Florida Phonk (Ski Mask style)", "Fast, energetic and gritty: bright presence, saturation and a quick slap. Inspired by their sound.", "eq{hp_on=1;hp_f=130;hp_s=0;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=11000;b5_g=2} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=7} > sat{mode=2;drive=12;mix=50} > delay{mode=0;sync=0;time=95;fb=10;lc=200;hc=6000;mix=14}", "Vocal Bus (Rage)", "comp{thr=-16;ratio=3;att=8;rel=90;knee=6;makeup=3} > widener{width=130;bass=120} > reverb{size=28;damp=50;pre=10;width=100;lc=300;hc=10000;mix=10}", "Lead");
        B("Pop Rap", "Queen Bars (Nicki Minaj style)", "Bright, punchy and versatile: strong presence, tight compression and a glossy plate. Inspired by their sound.", "eq{hp_on=1;hp_f=130;hp_s=0;b1_t=0;b1_f=320;b1_g=-2;b3_t=0;b3_f=3800;b3_g=3;b5_t=2;b5_f=12500;b5_g=3.5} > comp{thr=-25;ratio=4.5;att=4;rel=70;knee=6;makeup=6} > deess{freq=7500;thr=-29;range=10} > exciter{drive=8;harm=45;flo=4000;fhi=16000;mix=25} > reverb{size=30;damp=45;pre=10;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Pop Rap", "Bronx Energy (Cardi B style)", "Loud and in your face: bright, compressed hard, dry and punchy. Inspired by their sound.", "eq{hp_on=1;hp_f=130;hp_s=0;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=3600;b3_g=3.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-27;ratio=6;att=2;rel=55;knee=4;makeup=8} > deess{freq=7500;thr=-28;range=10} > sat{mode=0;drive=6;mix=30}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
        B("Pop Rap", "Hot Girl Bars (Megan Thee Stallion style)", "Confident and powerful: warm body, bright presence, tight compression, a small room. Inspired by their sound.", "eq{hp_on=1;hp_f=110;hp_s=0;b0_t=1;b0_f=180;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-2;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-26;ratio=5;att=3;rel=65;knee=6;makeup=7} > deess{freq=7200;thr=-29;range=10} > reverb{size=25;damp=55;pre=8;width=100;lc=200;hc=10000;mix=8}", "Vocal Bus (Trap)", "comp{thr=-18;ratio=2;att=30;rel=160;knee=8;makeup=2} > reverb{size=30;damp=55;pre=12;width=100;lc=250;hc=9000;mix=8}", "Lead");
