        B("Drill", "Soft Drill Flow (Ice Spice style)", "The calm, soft drill flow: close, smooth, bright top, dry. Inspired by their sound.", "eq{hp_on=1;hp_f=140;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3500;b3_g=2;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > deess{freq=7500;thr=-30;range=10} > reverb{size=15;damp=65;pre=5;width=100;lc=200;hc=10000;mix=5}", "Vocal Bus (Drill)", "comp{thr=-16;ratio=3;att=10;rel=100;knee=6;makeup=2} > reverb{size=18;damp=70;pre=6;width=100;lc=300;hc=8000;mix=5}", "Lead");
        B("R&B", "Ultra Silk R&B (SZA style)", "Breathy, intimate R&B singing: soft tune, airy top, gentle compression and a lush plate. Inspired by their sound.", "@Breath Control{reduce=8} > @Auto-Tune-Style Pitch Corrector{scale=0;speed=30;strength=85;natural=60;range=1} > eq{hp_on=1;hp_f=100;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3200;b3_g=1.5;b5_t=2;b5_f=13000;b5_g=4} > comp{thr=-21;ratio=2.5;att=18;rel=160;knee=6;makeup=3} > deess{freq=7500;thr=-31;range=9} > reverb{size=70;damp=35;pre=35;width=100;lc=200;hc=10000;mix=24}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
