        B("R&B", "Falsetto Glow (The Weeknd style)", "The glowing falsetto: soft tune, bright and airy, wide chorus and a huge shimmering reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=25;strength=100;natural=50;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3500;b3_g=2;b5_t=2;b5_f=13000;b5_g=4} > comp{thr=-22;ratio=3;att=12;rel=130;knee=6;makeup=4} > deess{freq=7500;thr=-30;range=10} > chorus{rate=0.5;depth=3;delay=14;spread=80;mix=22} > reverb{size=85;damp=35;pre=40;width=100;lc=300;hc=13000;mix=28}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
