        B("R&B", "Floaty Soul (Frank Ocean style)", "Dreamy and floaty: natural, soft, chorused with a big airy reverb. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=45;strength=65;natural=70;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;b3_t=0;b3_f=3000;b3_g=1.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-20;ratio=2.5;att=20;rel=170;knee=6;makeup=3} > chorus{rate=0.3;depth=4;delay=14;spread=100;mix=30} > reverb{size=80;damp=40;pre=35;width=100;lc=200;hc=10000;mix=26}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
