        B("Pop Rap", "Country Rap Pop (Lil Nas X style)", "Bright, glossy pop rap: tuned, wide, polished plate. Inspired by their sound.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=15;strength=100;natural=35;range=1} > eq{hp_on=1;hp_f=115;hp_s=0;b3_t=0;b3_f=3600;b3_g=2.5;b5_t=2;b5_f=12500;b5_g=3.5} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > widener{width=125;bass=120} > reverb{size=45;damp=40;pre=15;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
