        B("Singing", "Gospel Power", "Big gospel singing: rich, compressed for power, bright and a big church room.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=40;strength=70;natural=70;range=1} > eq{hp_on=1;hp_f=90;hp_s=0;b0_t=1;b0_f=180;b0_g=1.5;b3_t=0;b3_f=3000;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-24;ratio=4;att=10;rel=120;knee=6;makeup=5} > deess{freq=7000;thr=-30;range=9} > sat{mode=1;drive=5;mix=30} > reverb{size=85;damp=45;pre=40;width=100;lc=200;hc=10000;mix=26}", "Vocal Bus (Singer)", "comp{thr=-20;ratio=2;att=30;rel=200;knee=10;makeup=2} > reverb{size=75;damp=35;pre=40;width=100;lc=300;hc=13000;mix=22} > delay{mode=2;sync=3;time=375;fb=28;lc=200;hc=6000;mix=9}", "Lead");
