        B("Singing", "Octave Dream Sing", "A soft octave above the voice and a dreamy space: for floaty hooks.", "@Melody Tune: Octave Dream{scale=0} > eq{hp_on=1;hp_f=100;hp_s=0;b5_t=2;b5_f=12500;b5_g=3} > comp{thr=-22;ratio=3;att=12;rel=120;knee=6;makeup=4} > chorus{rate=0.4;depth=3;delay=14;spread=80;mix=25} > reverb{size=80;damp=40;pre=35;width=100;lc=200;hc=10000;mix=26}", "Vocal Bus (Singer)", "comp{thr=-20;ratio=2;att=30;rel=200;knee=10;makeup=2} > reverb{size=75;damp=35;pre=40;width=100;lc=300;hc=13000;mix=22} > delay{mode=2;sync=3;time=375;fb=28;lc=200;hc=6000;mix=9}", "Lead");
        B("Singing", "Power Lead Sing", "A powerful lead with a strong harmony: bright, compressed for punch, wide.", "@Melody Tune: Power Lead{scale=0} > eq{hp_on=1;hp_f=110;hp_s=0;b3_t=0;b3_f=3500;b3_g=2.5;b5_t=2;b5_f=12000;b5_g=3} > comp{thr=-24;ratio=4;att=6;rel=90;knee=6;makeup=5} > deess{freq=7200;thr=-30;range=10} > widener{width=125;bass=120} > reverb{size=55;damp=45;pre=20;width=100;lc=200;hc=10000;mix=16}", "Vocal Bus (Singer)", "comp{thr=-20;ratio=2;att=30;rel=200;knee=10;makeup=2} > reverb{size=75;damp=35;pre=40;width=100;lc=300;hc=13000;mix=22} > delay{mode=2;sync=3;time=375;fb=28;lc=200;hc=6000;mix=9}", "Lead");
