        B("R&B", "Trap R&B Lead", "The modern trap-R&B blend: tuned, warm, dark top and a slow echo.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=15;strength=100;natural=35;range=1} > eq{hp_on=1;hp_f=95;hp_s=0;lp_on=1;lp_f=14000;b0_t=1;b0_f=160;b0_g=1.5;b1_t=0;b1_f=320;b1_g=-1.5} > comp{thr=-23;ratio=3.5;att=10;rel=110;knee=6;makeup=4} > deess{freq=7000;thr=-30;range=9} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10} > reverb{size=60;damp=50;pre=25;width=100;lc=200;hc=10000;mix=16}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("R&B", "90s R&B", "A 90s R&B vocal: warm, smooth, slightly saturated with a bright plate.", "eq{hp_on=1;hp_f=95;hp_s=0;b0_t=1;b0_f=160;b0_g=1.5;b3_t=0;b3_f=3000;b3_g=2;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-22;ratio=3;att=12;rel=130;knee=6;makeup=4} > sat{mode=0;drive=5;mix=35} > reverb{size=55;damp=40;pre=20;width=100;lc=200;hc=10000;mix=18}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("R&B", "R&B Ad-Lib Runs", "For the runs and riffs behind the lead: thin, airy, wide and in a big reverb.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=25;strength=100;natural=50;range=1} > eq{hp_on=1;hp_f=200;hp_s=1;b5_t=2;b5_f=13000;b5_g=4} > comp{thr=-22;ratio=3;att=10;rel=110;knee=6;makeup=3} > widener{width=160;bass=120} > reverb{size=80;damp=35;pre=35;width=100;lc=200;hc=10000;mix=32}", null, null, "Lead");
        B("R&B", "Neo Soul", "Warm, organic neo soul: natural, round, tape-warm with a cosy room.", "eq{hp_on=1;hp_f=85;hp_s=0;lp_on=1;lp_f=13500;b0_t=1;b0_f=170;b0_g=2;b1_t=0;b1_f=340;b1_g=-1;b3_t=0;b3_f=2800;b3_g=1.5} > comp{thr=-20;ratio=2.5;att=20;rel=160;knee=6;makeup=3} > sat{mode=0;drive=7;mix=45} > reverb{size=40;damp=55;pre=15;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (R&B)", "comp{thr=-20;ratio=1.8;att=35;rel=200;knee=10;makeup=2} > reverb{size=65;damp=40;pre=35;width=100;lc=300;hc=12000;mix=20} > delay{mode=2;sync=1;time=500;fb=25;lc=200;hc=6000;mix=10}", "Lead");
        B("UK Rap", "UK Rap Polished", "A polished UK rap lead: light tune, clear presence, tight and almost dry.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=30;strength=60;natural=60;range=1} > eq{hp_on=1;hp_f=115;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3400;b3_g=2.5;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-25;ratio=4.5;att=4;rel=70;knee=6;makeup=6} > deess{freq=7000;thr=-30;range=10} > reverb{size=16;damp=70;pre=5;width=100;lc=200;hc=10000;mix=5}", "Vocal Bus (UK)", "comp{thr=-18;ratio=2.5;att=15;rel=120;knee=6;makeup=2} > reverb{size=22;damp=60;pre=8;width=100;lc=300;hc=9000;mix=6}", "Lead");
        B("UK Rap", "UK Melodic Rap", "Melodic UK rap: tuned, warm and close with a short echo on the line ends.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=10;strength=100;natural=30;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3300;b3_g=2.5;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-24;ratio=4;att=5;rel=80;knee=6;makeup=5} > deess{freq=7000;thr=-30;range=9} > @Rap Ad-Lib Echo{mix=14}", "Vocal Bus (UK)", "comp{thr=-18;ratio=2.5;att=15;rel=120;knee=6;makeup=2} > reverb{size=22;damp=60;pre=8;width=100;lc=300;hc=9000;mix=6}", "Lead");
        B("Drill", "NY Drill Lead", "A New York drill lead: shouted energy, gritty, bright, compressed hard and dry.", "eq{hp_on=1;hp_f=120;hp_s=0;b2_t=0;b2_f=1000;b2_g=1.5;b3_t=0;b3_f=3500;b3_g=3.5} > comp{thr=-27;ratio=6;att=2;rel=55;knee=4;makeup=8} > sat{mode=2;drive=10;mix=45} > deess{freq=7000;thr=-28;range=10}", "Vocal Bus (Drill)", "comp{thr=-16;ratio=3;att=10;rel=100;knee=6;makeup=2} > reverb{size=18;damp=70;pre=6;width=100;lc=300;hc=8000;mix=5}", "Lead");
        B("Drill", "Chicago Drill", "Raw Chicago drill: tuned roughly, dark top, gritty and tight.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=5;strength=85;natural=10;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;lp_on=1;lp_f=12000;b1_t=0;b1_f=300;b1_g=-2} > comp{thr=-26;ratio=5;att=4;rel=70;knee=6;makeup=6} > sat{mode=2;drive=9;mix=45}", "Vocal Bus (Drill)", "comp{thr=-16;ratio=3;att=10;rel=100;knee=6;makeup=2} > reverb{size=18;damp=70;pre=6;width=100;lc=300;hc=8000;mix=5}", "Lead");
        B("Emo & Rock Rap", "Pop Punk Rap", "Pop-punk energy: bright, doubled feel, compressed hard and a short room.", "eq{hp_on=1;hp_f=130;hp_s=0;b1_t=0;b1_f=300;b1_g=-2;b3_t=0;b3_f=3500;b3_g=3;b5_t=2;b5_f=11500;b5_g=3} > comp{thr=-26;ratio=5;att=3;rel=60;knee=6;makeup=6} > chorus{rate=1.2;depth=1.5;delay=10;spread=100;mix=18} > sat{mode=2;drive=8;mix=35} > reverb{size=30;damp=50;pre=10;width=100;lc=200;hc=10000;mix=10}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Emo & Rock Rap", "Emo Trap", "Sad emo trap: soft tune, warm, chorused and a long reverb.", "@Auto-Tune-Style Pitch Corrector{scale=0;speed=20;strength=100;natural=45;range=1} > eq{hp_on=1;hp_f=110;hp_s=0;b1_t=0;b1_f=300;b1_g=-1.5;b5_t=2;b5_f=11500;b5_g=2.5} > comp{thr=-23;ratio=3.5;att=8;rel=100;knee=6;makeup=4} > chorus{rate=0.4;depth=3;delay=14;spread=80;mix=28} > reverb{size=75;damp=55;pre=30;width=100;lc=200;hc=10000;mix=26}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Emo & Rock Rap", "Metal Scream", "For screamed parts: distortion, hard compression, telephone bite and a big room.", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > reverb{size=45;damp=50;pre=12;width=100;lc=200;hc=10000;mix=14}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Lead");
        B("Ad-libs & FX", "Phone Call Verse", "The voice comes through a phone: narrow, crunchy, a little noise.", "@Telephone Vocal > comp{thr=-22;ratio=4;att=5;rel=80;knee=6;makeup=5}", null, null, "Lead");
        B("Ad-libs & FX", "Radio Intro", "An old radio voice for intros and skits.", "@Radio Voice > comp{thr=-22;ratio=4;att=5;rel=80;knee=6;makeup=4} > reverb{size=20;damp=60;pre=6;width=100;lc=200;hc=10000;mix=6}", null, null, "Lead");
        B("Ad-libs & FX", "Megaphone Shout", "A megaphone for shout lines and hype.", "@Megaphone > comp{thr=-24;ratio=5;att=4;rel=70;knee=6;makeup=5}", null, null, "Lead");
        B("Ad-libs & FX", "Demon Voice Ad-Libs", "A deep demon layer under the voice for the dark ad-libs.", "@Demon Voice > eq{hp_on=1;hp_f=60;hp_s=0;lp_on=1;lp_f=9000} > comp{thr=-24;ratio=4;att=6;rel=80;knee=6;makeup=5} > reverb{size=40;damp=65;pre=12;width=100;lc=200;hc=10000;mix=14}", null, null, "Lead");
        B("Ad-libs & FX", "Chipmunk Ad-Libs", "High, squeaky ad-libs: formant and voice pushed up, bright and wide.", "@Formant Shifter{shift=6;tilt=3;mix=100} > eq{hp_on=1;hp_f=250;hp_s=1;b5_t=2;b5_f=12000;b5_g=4} > comp{thr=-22;ratio=4;att=5;rel=70;knee=6;makeup=4} > widener{width=160;bass=120}", null, null, "Lead");
