        B("Emo & Rock Rap", "Metal Scream - Spacey", "SPACEY version: a wide echo and a big room instead of the usual space. (Version of Metal Scream.)", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > @Worldwide Echo{mix=26} > reverb{size=85;damp=45;pre=35;width=100;lc=200;hc=10000;mix=26}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Spacey");
        B("Emo & Rock Rap", "Metal Scream - Dark", "DARK version: the top rolled off and warmed with tube, moodier. (Version of Metal Scream.)", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > reverb{size=45;damp=50;pre=12;width=100;lc=200;hc=10000;mix=14} > eq{lp_on=1;lp_f=9000;b0_t=1;b0_f=160;b0_g=1;b3_t=0;b3_f=3200;b3_g=-1.5} > sat{mode=1;drive=6;mix=30}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Dark");
        B("Emo & Rock Rap", "Metal Scream - Bright", "BRIGHT version: more presence and air, cuts through busy beats. (Version of Metal Scream.)", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > reverb{size=45;damp=50;pre=12;width=100;lc=200;hc=10000;mix=14} > eq{b3_t=0;b3_f=4000;b3_g=1.5;b5_t=2;b5_f=12500;b5_g=3} > exciter{drive=8;harm=50;flo=4500;fhi=16000;mix=22}", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Bright");
        B("Emo & Rock Rap", "Metal Scream - Radio", "RADIO version: the whole sound through an old radio, for intros, skits and switch-ups. (Version of Metal Scream.)", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > reverb{size=45;damp=50;pre=12;width=100;lc=200;hc=10000;mix=14} > @Radio Voice", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Radio");
        B("Emo & Rock Rap", "Metal Scream - Stutter", "STUTTER version: synced stutters and repeats chopped into the vocal for hype moments. (Version of Metal Scream.)", "eq{hp_on=1;hp_f=160;hp_s=1;b2_t=0;b2_f=1200;b2_g=3;b3_t=0;b3_f=3000;b3_g=3} > dist{mode=2;drive=20;tone=5000;mix=55;level=-6} > comp{thr=-28;ratio=8;att=2;rel=50;knee=4;makeup=7} > reverb{size=45;damp=50;pre=12;width=100;lc=200;hc=10000;mix=14} > @Stutter Edit", "Vocal Bus (Emo)", "comp{thr=-17;ratio=2.5;att=15;rel=140;knee=6;makeup=2} > reverb{size=55;damp=55;pre=20;width=100;lc=300;hc=9500;mix=15}", "Stutter");
